def max_rect2(cells):
    best=(0,None)
    heights=[0]*W
    for r in range(H):
        for c in range(W):
            heights[c]=heights[c]+1 if (r,c) in cells else 0
        stack=[]
        for c in range(W+1):
            cur=heights[c] if c<W else 0
            start=c
            while stack and stack[-1][1]>=cur:
                s0,hh=stack.pop()
                width=c-s0
                if hh*width>best[0]:
                    best=(hh*width,(r-hh+1,s0,r,c-1))
                start=s0
            stack.append((start,cur))
    return best

