def parse_rows(block):
    rows=[]
    for line in block.strip().split('\n'):
        toks=line.split()
        vals=[]
        for t in toks:
            if len(t)>1 and t.isdigit():
                vals.extend(int(ch) for ch in t)
            else:
                vals.append(int(t))
        rows.append(vals)
    return rows

