def get_pair(t, label):
    i1=t.find(label+' input'); i2=t.find(label+' output')
    din=t[i1:t.find('\n',i1):].split('\n',1)[1]
    rest=t[i2:t.find('\n',i2)].split('\n',1)[1]
    end=rest.find('Same instance')
    if end==-1: end=rest.find('Wrong attempts')
    dout=rest[:end] if end!=-1 else rest
    return parse_rows(din.strip()), parse_rows(dout.strip())

