def segment(t, start_label, end_labels):
    i=t.find(start_label); i=t.find('\n',i)+1
    ends=[t.find(e,i) for e in end_labels if t.find(e,i)!=-1]
    j=min(ends) if ends else len(t)
    return t[i:j].strip()

def pair(t, label):
    di=segment(t, label+' input', [label+' output'])
    do=segment(t, label+' output', ['Test input','Wrong attempts','Same instance'])
    return parse_rows(di), parse_rows(do)

