def comps_of(G):
    seen=set(); out=[]
    for r in range(30):
        for c in range(30):
            if (r,c) in seen: continue
            col=G[r][c]; stack=[(r,c)]; comp=[]; seen.add((r,c))
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=a+dr,b+dc
                    if 0<=nr<30 and 0<=nc<30 and (nr,nc) not in seen and G[nr][nc]==col:
                        seen.add((nr,nc)); stack.append((nr,nc))
            out.append((col,comp))
    return out

